CREATE TYPE "CohortStatus" AS ENUM ('DRAFT','OPEN','ACTIVE','COMPLETED','CANCELLED','ARCHIVED');
CREATE TYPE "AcademicGroupModality" AS ENUM ('ONLINE','IN_PERSON','HYBRID');
CREATE TYPE "AcademicGroupStatus" AS ENUM ('DRAFT','ACTIVE','COMPLETED','CANCELLED','ARCHIVED');
CREATE TYPE "AcademicEnrollmentStatus" AS ENUM ('PENDING','ACTIVE','SUSPENDED','COMPLETED','CANCELLED','DROPPED');
CREATE TYPE "AcademicTeacherRole" AS ENUM ('COHORT_MANAGER','PRIMARY','SECONDARY');
CREATE TYPE "AcademicSessionStatus" AS ENUM ('SCHEDULED','IN_PROGRESS','COMPLETED','CANCELLED','RESCHEDULED');
CREATE TYPE "AcademicAttendanceStatus" AS ENUM ('PRESENT','LATE','ABSENT','EXCUSED','TECHNICAL_ISSUE');
ALTER TYPE "NotificationType" ADD VALUE IF NOT EXISTS 'ENROLLMENT_CREATED';
ALTER TYPE "NotificationType" ADD VALUE IF NOT EXISTS 'ENROLLMENT_UPDATED';
ALTER TYPE "NotificationType" ADD VALUE IF NOT EXISTS 'ENROLLMENT_SUSPENDED';
ALTER TYPE "NotificationType" ADD VALUE IF NOT EXISTS 'GROUP_ASSIGNED';
ALTER TYPE "NotificationType" ADD VALUE IF NOT EXISTS 'ACADEMIC_SESSION_SCHEDULED';
ALTER TYPE "NotificationType" ADD VALUE IF NOT EXISTS 'ACADEMIC_SESSION_UPDATED';
ALTER TYPE "NotificationType" ADD VALUE IF NOT EXISTS 'ACADEMIC_SESSION_CANCELLED';
ALTER TYPE "NotificationType" ADD VALUE IF NOT EXISTS 'ATTENDANCE_RECORDED';

CREATE TABLE "academic_levels" ("id" SERIAL PRIMARY KEY,"name" TEXT NOT NULL,"code" TEXT NOT NULL,"description" TEXT,"position" INTEGER NOT NULL,"is_active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "academic_levels_position_check" CHECK ("position">0));
CREATE TABLE "academic_cohorts" ("id" SERIAL PRIMARY KEY,"name" TEXT NOT NULL,"code" TEXT NOT NULL,"level_id" INTEGER NOT NULL,"course_id" INTEGER NOT NULL,"start_date" TIMESTAMP(3) NOT NULL,"end_date" TIMESTAMP(3) NOT NULL,"capacity" INTEGER NOT NULL,"status" "CohortStatus" NOT NULL DEFAULT 'DRAFT',"academic_manager_id" INTEGER,"description" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "academic_cohorts_period_check" CHECK ("end_date">"start_date"),CONSTRAINT "academic_cohorts_capacity_check" CHECK ("capacity">0));
CREATE TABLE "academic_groups" ("id" SERIAL PRIMARY KEY,"cohort_id" INTEGER NOT NULL,"name" TEXT NOT NULL,"code" TEXT NOT NULL,"capacity" INTEGER NOT NULL,"modality" "AcademicGroupModality" NOT NULL,"location_or_url" TEXT,"usual_days" TEXT[] DEFAULT ARRAY[]::TEXT[],"usual_start_time" TEXT,"usual_end_time" TEXT,"status" "AcademicGroupStatus" NOT NULL DEFAULT 'DRAFT',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "academic_groups_capacity_check" CHECK ("capacity">0));
CREATE TABLE "academic_enrollments" ("id" SERIAL PRIMARY KEY,"student_id" INTEGER NOT NULL,"cohort_id" INTEGER NOT NULL,"group_id" INTEGER,"entry_level_id" INTEGER,"enrolled_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"status" "AcademicEnrollmentStatus" NOT NULL DEFAULT 'PENDING',"source" TEXT,"administrative_notes" TEXT,"suspended_at" TIMESTAMP(3),"ended_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "academic_group_transfers" ("id" SERIAL PRIMARY KEY,"enrollment_id" INTEGER NOT NULL,"from_group_id" INTEGER,"to_group_id" INTEGER NOT NULL,"transferred_by_id" INTEGER NOT NULL,"reason" TEXT NOT NULL,"transferred_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "academic_teacher_assignments" ("id" SERIAL PRIMARY KEY,"teacher_id" INTEGER NOT NULL,"cohort_id" INTEGER NOT NULL,"group_id" INTEGER,"role" "AcademicTeacherRole" NOT NULL,"starts_at" TIMESTAMP(3) NOT NULL,"ends_at" TIMESTAMP(3),"removed_at" TIMESTAMP(3),"assigned_by_id" INTEGER NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "academic_teacher_assignment_period_check" CHECK ("ends_at" IS NULL OR "ends_at">="starts_at"));
CREATE TABLE "academic_sessions" ("id" SERIAL PRIMARY KEY,"group_id" INTEGER NOT NULL,"lesson_id" INTEGER,"teacher_id" INTEGER NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"starts_at" TIMESTAMP(3) NOT NULL,"ends_at" TIMESTAMP(3) NOT NULL,"modality" "AcademicGroupModality" NOT NULL,"location_or_url" TEXT,"status" "AcademicSessionStatus" NOT NULL DEFAULT 'SCHEDULED',"cancellation_reason" TEXT,"internal_notes" TEXT,"rescheduled_from_id" INTEGER,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "academic_sessions_period_check" CHECK ("ends_at">"starts_at"));
CREATE TABLE "academic_attendances" ("id" SERIAL PRIMARY KEY,"session_id" INTEGER NOT NULL,"enrollment_id" INTEGER NOT NULL,"status" "AcademicAttendanceStatus" NOT NULL,"arrived_at" TIMESTAMP(3),"left_at" TIMESTAMP(3),"late_minutes" INTEGER NOT NULL DEFAULT 0,"comment" TEXT,"justification" TEXT,"recorded_by_id" INTEGER NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "academic_attendance_late_check" CHECK ("late_minutes">=0),CONSTRAINT "academic_attendance_times_check" CHECK ("left_at" IS NULL OR "arrived_at" IS NULL OR "left_at">="arrived_at"));
CREATE TABLE "academic_audit_logs" ("id" SERIAL PRIMARY KEY,"actor_id" INTEGER NOT NULL,"entity_type" TEXT NOT NULL,"entity_id" INTEGER NOT NULL,"action" TEXT NOT NULL,"before_data" JSONB,"after_data" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE UNIQUE INDEX "academic_levels_code_key" ON "academic_levels"("code"); CREATE UNIQUE INDEX "academic_levels_position_key" ON "academic_levels"("position"); CREATE INDEX "academic_levels_is_active_position_idx" ON "academic_levels"("is_active","position");
CREATE UNIQUE INDEX "academic_cohorts_code_key" ON "academic_cohorts"("code"); CREATE INDEX "academic_cohorts_level_id_status_idx" ON "academic_cohorts"("level_id","status"); CREATE INDEX "academic_cohorts_course_id_status_idx" ON "academic_cohorts"("course_id","status"); CREATE INDEX "academic_cohorts_academic_manager_id_idx" ON "academic_cohorts"("academic_manager_id"); CREATE INDEX "academic_cohorts_start_date_end_date_idx" ON "academic_cohorts"("start_date","end_date");
CREATE UNIQUE INDEX "academic_groups_cohort_id_code_key" ON "academic_groups"("cohort_id","code"); CREATE INDEX "academic_groups_cohort_id_status_idx" ON "academic_groups"("cohort_id","status");
CREATE UNIQUE INDEX "academic_enrollments_student_id_cohort_id_key" ON "academic_enrollments"("student_id","cohort_id"); CREATE INDEX "academic_enrollments_cohort_id_status_idx" ON "academic_enrollments"("cohort_id","status"); CREATE INDEX "academic_enrollments_group_id_status_idx" ON "academic_enrollments"("group_id","status"); CREATE INDEX "academic_enrollments_student_id_status_idx" ON "academic_enrollments"("student_id","status");
CREATE INDEX "academic_group_transfers_enrollment_id_transferred_at_idx" ON "academic_group_transfers"("enrollment_id","transferred_at"); CREATE INDEX "academic_group_transfers_from_group_id_idx" ON "academic_group_transfers"("from_group_id"); CREATE INDEX "academic_group_transfers_to_group_id_idx" ON "academic_group_transfers"("to_group_id");
CREATE INDEX "academic_teacher_assignments_teacher_id_starts_at_ends_at_idx" ON "academic_teacher_assignments"("teacher_id","starts_at","ends_at"); CREATE INDEX "academic_teacher_assignments_cohort_id_removed_at_idx" ON "academic_teacher_assignments"("cohort_id","removed_at"); CREATE INDEX "academic_teacher_assignments_group_id_removed_at_idx" ON "academic_teacher_assignments"("group_id","removed_at");
CREATE INDEX "academic_sessions_group_id_starts_at_ends_at_idx" ON "academic_sessions"("group_id","starts_at","ends_at"); CREATE INDEX "academic_sessions_teacher_id_starts_at_ends_at_idx" ON "academic_sessions"("teacher_id","starts_at","ends_at"); CREATE INDEX "academic_sessions_status_starts_at_idx" ON "academic_sessions"("status","starts_at"); CREATE INDEX "academic_sessions_rescheduled_from_id_idx" ON "academic_sessions"("rescheduled_from_id");
CREATE UNIQUE INDEX "academic_attendances_session_id_enrollment_id_key" ON "academic_attendances"("session_id","enrollment_id"); CREATE INDEX "academic_attendances_enrollment_id_created_at_idx" ON "academic_attendances"("enrollment_id","created_at"); CREATE INDEX "academic_attendances_session_id_status_idx" ON "academic_attendances"("session_id","status");
CREATE INDEX "academic_audit_logs_entity_type_entity_id_created_at_idx" ON "academic_audit_logs"("entity_type","entity_id","created_at"); CREATE INDEX "academic_audit_logs_actor_id_created_at_idx" ON "academic_audit_logs"("actor_id","created_at");

ALTER TABLE "academic_cohorts" ADD FOREIGN KEY ("level_id") REFERENCES "academic_levels"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("course_id") REFERENCES "courses"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("academic_manager_id") REFERENCES "users"("id") ON DELETE SET NULL;
ALTER TABLE "academic_groups" ADD FOREIGN KEY ("cohort_id") REFERENCES "academic_cohorts"("id") ON DELETE RESTRICT;
ALTER TABLE "academic_enrollments" ADD FOREIGN KEY ("student_id") REFERENCES "users"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("cohort_id") REFERENCES "academic_cohorts"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("group_id") REFERENCES "academic_groups"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("entry_level_id") REFERENCES "academic_levels"("id") ON DELETE SET NULL;
ALTER TABLE "academic_group_transfers" ADD FOREIGN KEY ("enrollment_id") REFERENCES "academic_enrollments"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("from_group_id") REFERENCES "academic_groups"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("to_group_id") REFERENCES "academic_groups"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("transferred_by_id") REFERENCES "users"("id") ON DELETE RESTRICT;
ALTER TABLE "academic_teacher_assignments" ADD FOREIGN KEY ("teacher_id") REFERENCES "users"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("cohort_id") REFERENCES "academic_cohorts"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("group_id") REFERENCES "academic_groups"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("assigned_by_id") REFERENCES "users"("id") ON DELETE RESTRICT;
ALTER TABLE "academic_sessions" ADD FOREIGN KEY ("group_id") REFERENCES "academic_groups"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("lesson_id") REFERENCES "lessons"("id") ON DELETE SET NULL, ADD FOREIGN KEY ("teacher_id") REFERENCES "users"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("rescheduled_from_id") REFERENCES "academic_sessions"("id") ON DELETE SET NULL;
ALTER TABLE "academic_attendances" ADD FOREIGN KEY ("session_id") REFERENCES "academic_sessions"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("enrollment_id") REFERENCES "academic_enrollments"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("recorded_by_id") REFERENCES "users"("id") ON DELETE RESTRICT;
ALTER TABLE "academic_audit_logs" ADD FOREIGN KEY ("actor_id") REFERENCES "users"("id") ON DELETE RESTRICT;
